const buttons=[...controls.querySelectorAll('button')],motion=matchMedia('(prefers-reduced-motion:reduce)'),states=[['01 / LIGATURE','左の形。線を分かち合う。','MとNが斜線と支柱を共有し、Aは右に立つ。四つの文字の関係がまだ横方向へ開いている段階です。'],['02 / INTERLOCK','中央の形。中心へ重ねる。','左右の支柱と斜線を寄せ、Aの骨格がMとNの内側へ入っていく。線が交差しながら、同じ領域を共有し始めます。'],['03 / CONVERGENCE','右の形。同じ骨格に収める。','Mの谷、Nの斜線、Aの頂点と横画が同じスクエアに収束。交点を整理して、一体の輪郭にしています。']];let value=0,raf=0,last=0,running=false,inView=true;
function render(v){value=Math.max(0,Math.min(100,v));const n=Math.round(value);shape.setAttribute('d',FRAMES[n]);range.value=String(n);document.getElementById('morph-value').textContent=n+'%';const stage=n<25?0:n<75?1:2;root.dataset.stage=String(stage);buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===stage)));['stage-number','stage-title','stage-description'].forEach((id,i)=>document.getElementById(id).textContent=states[stage][i]);}
function stop(){running=false;cancelAnimationFrame(raf);raf=0;last=0;play.textContent='左から右へ再生';play.setAttribute('aria-pressed','false');}
function tick(t){if(!running)return;if(!document.hidden&&inView){if(last)render(value+(t-last)/38);if(value>=100){stop();document.getElementById('morph-status').textContent='右の一体形になりました。';return;}}last=t;raf=requestAnimationFrame(tick);}
