buttons.forEach((b,i)=>{const choose=()=>{stop();render(i*50);};b.addEventListener('click',choose);b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%3;else if(e.key==='ArrowLeft')n=(i+2)%3;else if(e.key==='Home')n=0;else if(e.key==='End')n=2;else return;e.preventDefault();stop();render(n*50);buttons[n].focus();});});range.addEventListener('input',()=>{stop();render(Number(range.value));});play.addEventListener('click',start);reset.addEventListener('click',()=>{stop();render(0);});document.addEventListener('visibilitychange',()=>{last=0;});if('IntersectionObserver'in window)new IntersectionObserver(e=>{inView=e[0].isIntersecting;last=0;},{threshold:.05}).observe(root);function preference(){stop();play.disabled=motion.matches;document.getElementById('motion-note').textContent=motion.matches?'動きを減らす設定を尊重し、自動補間を停止しています。スライダーと3段階のボタンで確認できます。':'自動再生しません。スライダーで任意の位置を確かめられます。';}motion.addEventListener('change',preference);window.addEventListener('pagehide',stop);controls.hidden=false;document.querySelector('.morph-tools').hidden=false;preference();render(0);

